import { redirectToApp, serviceClient } from '../_shared/oauth.ts';
import { getCredentials } from '../_shared/credentials.ts';
import { consumeOAuthState } from '../_shared/genericOAuth2.ts';

async function exchangeCode(clientKey: string, clientSecret: string, redirectUri: string, code: string, codeVerifier: string) {
  const body = new URLSearchParams({
    client_key: clientKey,
    client_secret: clientSecret,
    code,
    grant_type: 'authorization_code',
    redirect_uri: redirectUri,
    code_verifier: codeVerifier,
  });
  const res = await fetch('https://open.tiktokapis.com/v2/oauth/token/', {
    method: 'POST',
    headers: { 'Content-Type': 'application/x-www-form-urlencoded', 'Cache-Control': 'no-cache' },
    body,
  });
  if (!res.ok) {
    const detail = await res.text();
    console.error(`[tiktok-oauth-callback] token exchange failed (HTTP ${res.status}): ${detail}`);
    // TikTok's token error bodies are JSON like { error, error_description }.
    // Try to surface the human-readable description; fall back to raw text.
    let parsed: { error_description?: string; error?: string } | null = null;
    try {
      parsed = JSON.parse(detail);
    } catch {
      parsed = null;
    }
    const message = parsed?.error_description || parsed?.error || `token exchange failed (HTTP ${res.status}): ${detail.slice(0, 300)}`;
    throw new Error(message);
  }
  return (await res.json()) as { access_token: string; expires_in: number; refresh_token: string; refresh_expires_in: number; open_id: string };
}

async function fetchProfile(accessToken: string) {
  const url = new URL('https://open.tiktokapis.com/v2/user/info/');
  url.searchParams.set('fields', 'open_id,display_name');
  const res = await fetch(url.toString(), { headers: { Authorization: `Bearer ${accessToken}` } });
  if (!res.ok) {
    const detail = await res.text();
    console.error(`[tiktok-oauth-callback] profile fetch failed (HTTP ${res.status}): ${detail}`);
    throw new Error(`profile fetch failed (HTTP ${res.status}): ${detail.slice(0, 300)}`);
  }
  const body = await res.json();
  if (!body?.data?.user) {
    console.error(`[tiktok-oauth-callback] profile response had no data.user: ${JSON.stringify(body)}`);
    throw new Error('profile fetch returned an unexpected shape');
  }
  return body.data.user as { open_id: string; display_name: string };
}

Deno.serve(async (req: Request) => {
  const supabase = serviceClient();
  const url = new URL(req.url);
  const code = url.searchParams.get('code');
  const state = url.searchParams.get('state');
  const oauthError = url.searchParams.get('error_description') ?? url.searchParams.get('error');

  if (oauthError) {
    console.error(`[tiktok-oauth-callback] TikTok returned an OAuth error: ${oauthError}`);
    return await redirectToApp(supabase, { platform: 'tiktok', error: oauthError });
  }
  if (!code || !state) {
    console.error(`[tiktok-oauth-callback] missing code or state in callback URL: ${req.url}`);
    return await redirectToApp(supabase, { platform: 'tiktok', error: 'missing_code_or_state' });
  }

  const creds = await getCredentials(supabase, ['tiktok_client_key', 'tiktok_client_secret']);
  if (!creds.tiktok_client_key || !creds.tiktok_client_secret) {
    console.error('[tiktok-oauth-callback] tiktok_client_key/tiktok_client_secret not configured (Settings > Integrations or TIKTOK_CLIENT_KEY/TIKTOK_CLIENT_SECRET env vars)');
    return await redirectToApp(supabase, { platform: 'tiktok', error: 'server_not_configured' });
  }

  const consumed = await consumeOAuthState(supabase, 'tiktok', state);
  if (!consumed || !consumed.code_verifier) {
    console.error(`[tiktok-oauth-callback] invalid, expired, or already-consumed state (or missing code_verifier): ${state}`);
    return await redirectToApp(supabase, { platform: 'tiktok', error: 'invalid_or_expired_state' });
  }

  const functionsUrl = Deno.env.get('SUPABASE_URL')!.replace('.supabase.co', '.supabase.co/functions/v1');
  const redirectUri = `${functionsUrl}/tiktok-oauth-callback`;

  try {
    const token = await exchangeCode(creds.tiktok_client_key, creds.tiktok_client_secret, redirectUri, code, consumed.code_verifier);
    const profile = await fetchProfile(token.access_token);
    const expiresAt = new Date(Date.now() + token.expires_in * 1000).toISOString();

    const { error } = await supabase.from('connected_accounts').upsert(
      {
        workspace_id: consumed.workspace_id,
        platform: 'tiktok',
        handle: profile.display_name,
        provider_account_id: profile.open_id,
        access_token_encrypted: token.access_token,
        refresh_token_encrypted: token.refresh_token,
        token_expires_at: expiresAt,
        status: 'connected',
        sync_status: 'synced',
        health_status: 'healthy',
        last_synced_at: new Date().toISOString(),
        // TikTok's Content Posting API restricts unaudited apps to private/
        // self-view publishing — surfaced on the Accounts card so it isn't a
        // surprise the first time a scheduled post "publishes" but stays
        // invisible to followers until the app passes review.
        metadata: { connected_by: consumed.user_id, refresh_token_expires_at: new Date(Date.now() + token.refresh_expires_in * 1000).toISOString() },
      },
      { onConflict: 'workspace_id,platform,provider_account_id', ignoreDuplicates: false },
    );
    if (error) {
      console.error(`[tiktok-oauth-callback] connected_accounts upsert failed: ${error.message}`);
      throw new Error(error.message);
    }

    return await redirectToApp(supabase, { platform: 'tiktok', connected: '1' });
  } catch (e) {
    const message = e instanceof Error ? e.message : 'unknown_error';
    console.error(`[tiktok-oauth-callback] connect flow failed: ${message}`);
    // Cap the length so an unusually verbose upstream error can't blow past
    // typical URL/redirect length limits — the full detail is still in the logs above.
    return await redirectToApp(supabase, { platform: 'tiktok', error: message.slice(0, 300) });
  }
});

import { createClient, SupabaseClient } from 'npm:@supabase/supabase-js@2.57.4';
import { getCredential } from './credentials.ts';

export const corsHeaders = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Methods': 'GET, POST, OPTIONS',
  'Access-Control-Allow-Headers': 'Content-Type, Authorization, X-Client-Info, Apikey',
};

export function jsonResponse(body: unknown, status = 200): Response {
  return new Response(JSON.stringify(body), {
    status,
    headers: { ...corsHeaders, 'Content-Type': 'application/json' },
  });
}

export function errorResponse(message: string, status = 400): Response {
  return jsonResponse({ error: message }, status);
}

/** Redirect back into the app's Connected Accounts page with an outcome.
 * Resolves the base URL from Settings > Integrations first, falling back
 * to the APP_URL env var if nothing's been saved there yet. */
export async function redirectToApp(supabase: SupabaseClient, params: Record<string, string>): Promise<Response> {
  const appUrl = (await getCredential(supabase, 'app_url')) ?? '';
  const url = new URL(`${appUrl.replace(/\/$/, '')}/app/accounts`);
  for (const [key, value] of Object.entries(params)) url.searchParams.set(key, value);
  return new Response(null, { status: 302, headers: { Location: url.toString() } });
}

export function serviceClient(): SupabaseClient {
  const supabaseUrl = Deno.env.get('SUPABASE_URL')!;
  const serviceKey = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')!;
  return createClient(supabaseUrl, serviceKey, { auth: { autoRefreshToken: false, persistSession: false } });
}

/** Verifies the caller's bearer token and returns their user id, or null. */
export async function getCallerId(supabase: SupabaseClient, req: Request): Promise<string | null> {
  const authHeader = req.headers.get('Authorization');
  if (!authHeader?.startsWith('Bearer ')) return null;
  const { data, error } = await supabase.auth.getUser(authHeader.slice(7));
  if (error || !data.user) return null;
  return data.user.id;
}

export function randomState(): string {
  return crypto.randomUUID().replace(/-/g, '') + crypto.randomUUID().replace(/-/g, '');
}

import { SupabaseClient } from 'npm:@supabase/supabase-js@2.57.4';

/** Known credential keys the Settings > Integrations page can save, and the
 * env var each falls back to if nothing's been saved in the DB yet (so
 * existing dashboard/CLI-configured secrets keep working). */
const ENV_FALLBACK: Record<string, string> = {
  meta_app_id: 'META_APP_ID',
  meta_app_secret: 'META_APP_SECRET',
  meta_config_id: 'META_CONFIG_ID',
  linkedin_client_id: 'LINKEDIN_CLIENT_ID',
  linkedin_client_secret: 'LINKEDIN_CLIENT_SECRET',
  x_client_id: 'X_CLIENT_ID',
  x_client_secret: 'X_CLIENT_SECRET',
  threads_app_id: 'THREADS_APP_ID',
  threads_app_secret: 'THREADS_APP_SECRET',
  tiktok_client_key: 'TIKTOK_CLIENT_KEY',
  tiktok_client_secret: 'TIKTOK_CLIENT_SECRET',
  app_url: 'APP_URL',
};

/** Resolves one credential: DB value (set from the app) takes priority,
 * falling back to the matching env var. Returns null if neither is set. */
export async function getCredential(supabase: SupabaseClient, key: string): Promise<string | null> {
  const { data } = await supabase.from('platform_credentials').select('value').eq('key', key).maybeSingle();
  if (data?.value) return data.value;
  const envKey = ENV_FALLBACK[key];
  return envKey ? Deno.env.get(envKey) ?? null : null;
}

/** Resolves several credentials in one round trip. */
export async function getCredentials(supabase: SupabaseClient, keys: string[]): Promise<Record<string, string | null>> {
  const { data } = await supabase.from('platform_credentials').select('key, value').in('key', keys);
  const fromDb = new Map((data ?? []).map((row) => [row.key as string, row.value as string]));
  const result: Record<string, string | null> = {};
  for (const key of keys) {
    result[key] = fromDb.get(key) || (ENV_FALLBACK[key] ? Deno.env.get(ENV_FALLBACK[key]) ?? null : null);
  }
  return result;
}

import { SupabaseClient } from 'npm:@supabase/supabase-js@2.57.4';
import { errorResponse, getCallerId, jsonResponse, randomState } from './oauth.ts';
import { getCredential } from './credentials.ts';
import { generateCodeVerifier, codeChallengeFromVerifier } from './pkce.ts';

export type OAuth2ConnectConfig = {
  platform: 'x' | 'threads' | 'tiktok';
  clientIdCredentialKey: string;
  clientIdMissingMessage: string;
  authorizeUrl: string;
  /** Query param name the provider expects for the client id ('client_id' for
   * most, but TikTok calls it 'client_key'). */
  clientIdParam: string;
  scope: string;
  scopeParam?: string; // defaults to 'scope'
  usesPkce: boolean;
  redirectUriFunctionName: string; // e.g. 'x-oauth-callback'
  extraAuthorizeParams?: Record<string, string>;
};

/** Starts a redirect-based OAuth2 flow: checks the caller belongs to the
 * workspace, stores a CSRF state row (plus a PKCE verifier when required),
 * and returns the provider's authorize URL for the frontend to redirect to.
 * Shared by x-oauth-connect, threads-oauth-connect, and tiktok-oauth-connect
 * so the CSRF/PKCE bookkeeping isn't reimplemented three times. */
export async function startOAuth2Connect(supabase: SupabaseClient, req: Request, config: OAuth2ConnectConfig): Promise<Response> {
  if (req.method !== 'POST') return errorResponse('Method not allowed', 405);

  const clientId = await getCredential(supabase, config.clientIdCredentialKey);
  if (!clientId) {
    console.error(`[${config.platform}-oauth-connect] ${config.clientIdMissingMessage}`);
    return errorResponse(config.clientIdMissingMessage, 500);
  }

  const callerId = await getCallerId(supabase, req);
  if (!callerId) {
    console.error(`[${config.platform}-oauth-connect] Unauthorized: missing or invalid bearer token`);
    return errorResponse('Unauthorized', 401);
  }

  const { workspace_id } = await req.json().catch(() => ({}));
  if (!workspace_id) {
    console.error(`[${config.platform}-oauth-connect] workspace_id missing from request body`);
    return errorResponse('workspace_id is required', 400);
  }

  const { data: membership } = await supabase
    .from('workspace_members')
    .select('id')
    .eq('workspace_id', workspace_id)
    .eq('user_id', callerId)
    .maybeSingle();
  if (!membership) {
    console.error(`[${config.platform}-oauth-connect] Forbidden: user ${callerId} is not a member of workspace ${workspace_id}`);
    return errorResponse('Forbidden', 403);
  }

  const state = randomState();
  const codeVerifier = config.usesPkce ? generateCodeVerifier() : null;

  const { error } = await supabase.from('oauth_states').insert({
    state,
    workspace_id,
    user_id: callerId,
    platform: config.platform,
    code_verifier: codeVerifier,
  });
  // Surface the actual DB error (e.g. a stale platform CHECK constraint, or a
  // missing oauth_states.code_verifier column) instead of a generic message —
  // this is what used to show up to the user as an opaque "non-2xx" toast.
  if (error) {
    console.error(`[${config.platform}-oauth-connect] oauth_states insert failed: ${error.message}`);
    return errorResponse(`Could not start OAuth flow: ${error.message}`, 500);
  }

  const functionsUrl = Deno.env.get('SUPABASE_URL')!.replace('.supabase.co', '.supabase.co/functions/v1');
  const redirectUri = `${functionsUrl}/${config.redirectUriFunctionName}`;

  const authorizeUrl = new URL(config.authorizeUrl);
  authorizeUrl.searchParams.set(config.clientIdParam, clientId);
  authorizeUrl.searchParams.set('redirect_uri', redirectUri);
  authorizeUrl.searchParams.set('state', state);
  authorizeUrl.searchParams.set('response_type', 'code');
  authorizeUrl.searchParams.set(config.scopeParam ?? 'scope', config.scope);
  if (config.usesPkce && codeVerifier) {
    authorizeUrl.searchParams.set('code_challenge', await codeChallengeFromVerifier(codeVerifier));
    authorizeUrl.searchParams.set('code_challenge_method', 'S256');
  }
  for (const [key, value] of Object.entries(config.extraAuthorizeParams ?? {})) {
    authorizeUrl.searchParams.set(key, value);
  }

  return jsonResponse({ url: authorizeUrl.toString() });
}

export type ConsumedState = { workspace_id: string; user_id: string; code_verifier: string | null };

/** Validates and deletes an OAuth CSRF state row, returning the workspace/user
 * it was issued for (and PKCE verifier, if any). Shared by every callback. */
export async function consumeOAuthState(supabase: SupabaseClient, platform: string, state: string | null): Promise<ConsumedState | null> {
  if (!state) return null;
  const { data: stateRow } = await supabase.from('oauth_states').select('*').eq('state', state).eq('platform', platform).maybeSingle();
  if (!stateRow || new Date(stateRow.expires_at as string) < new Date()) return null;
  await supabase.from('oauth_states').delete().eq('id', stateRow.id as string);
  return {
    workspace_id: stateRow.workspace_id as string,
    user_id: stateRow.user_id as string,
    code_verifier: (stateRow.code_verifier as string | null) ?? null,
  };
}

/** RFC 7636 PKCE helpers, shared by every OAuth2 provider that requires it
 * (currently X and TikTok — Meta and LinkedIn's classic 3-legged flows don't). */

function base64UrlEncode(bytes: Uint8Array): string {
  let str = '';
  for (const b of bytes) str += String.fromCharCode(b);
  return btoa(str).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
}

export function generateCodeVerifier(): string {
  const bytes = new Uint8Array(32);
  crypto.getRandomValues(bytes);
  return base64UrlEncode(bytes);
}

export async function codeChallengeFromVerifier(verifier: string): Promise<string> {
  const digest = await crypto.subtle.digest('SHA-256', new TextEncoder().encode(verifier));
  return base64UrlEncode(new Uint8Array(digest));
}
